 */

#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <vector>
#include <algorithm>
#include "knn.h"

// Software reference implementation of KNN
void sw_knn(const std::vector<std::vector<float>>& search_space,
            const std::vector<float>& query,
            int K,
            std::vector<float>& out_distances,
            std::vector<int>& out_indices) {
